//A mandelbrot where the update is deflected towards attractors using
//something similar to gravity.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    #define AA 3  // Anti-aliasing level (2 = 4 samples, 3 = 9 samples)

    vec3 totalCol = vec3(0.0);
    const float max_iter = 150.0;
    vec2 attractor_point1 = vec2(cos(iTime*0.5),sin(iTime*0.5)) * (0.5 + abs(sin(iTime*0.1)));
    vec2 attractor_point2 = vec2(cos(iTime*0.3+1.3),sin(iTime*0.3+1.3)) * (0.5 +abs(sin(iTime*0.15 +0.3)));

    for(int x = 0; x < AA; x++) {
        for(int y = 0; y < AA; y++) {
            // Sub-pixel offset calculation
            vec2 offset = (vec2(x, y) + 0.5) / float(AA) - 0.5;
            vec2 subCoord = fragCoord + offset;

            // Calculate fractal for this sub-pixel
            vec2 uv = (2.0 * subCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
            uv *= 1.0;

            vec2 c = uv;
            vec2 z = vec2(0.0);
            float iterations = 0.0;

            for (float i = 0.0; i < max_iter; i++) {

                vec2 z_mandel = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
                vec2 deflection = vec2(0.0,0.0);

                //in the deflected mandelbrot set, attract its updated
                //position to the two attractors using inverse square.
                {
                    vec2 dir = attractor_point1-z;
                    vec2 norm = normalize(dir);
                    float dist = length(dir)*2.0;
                    float strength = (1.0f / pow(dist,2.0))*0.5;
                    deflection += norm * strength;
                }

                {
                    vec2 dir = attractor_point2-z;
                    vec2 norm = normalize(dir);
                    float dist = length(dir)*2.0;
                    float strength = (1.0f / pow(dist,2.0))*0.5;
                    deflection += norm * strength;
                } 



                vec2 grav = z_mandel + deflection;
                z = mix(z_mandel, grav, abs(cos(iTime*0.05)));

                if (dot(z, z) > 4.0) break;
                iterations++;
            }

            // Enhanced smooth coloring with distance estimation
            float dist = length(z);
            float smooth_iter = iterations + 1.0 - log2(log(max(dist, 4.0)) / log(4.0));
            float t = smooth_iter / max_iter;

            // Color calculation
            vec3 col = 0.5 + 0.5*cos(vec3(sin(pow(t,0.1)*3.0+0.2), cos(pow(t,0.1)*3.0), sin(pow(t,0.1)*3.0)) + t * 10.0);
            col *= smoothstep(0.0, 0.1, t);

            totalCol += col;
        }
    }

    // Average samples and apply gamma correction
    totalCol /= float(AA*AA);
    totalCol = pow(totalCol, vec3(1.0/2.2));

    fragColor = vec4(totalCol, 1.0);
}
